// Arma un aviso legible con lo que n8n entrega en el Error Trigger.
const w = $json.workflow || {};
const e = $json.execution || {};
return [{
  json: {
    flujo: w.name || 'sin nombre',
    nodo: (e.lastNodeExecuted) || (e.error && e.error.node && e.error.node.name) || 'desconocido',
    mensaje: (e.error && e.error.message) || 'sin detalle',
    ejecucion: e.id || '',
    enlace: e.url || '',
    cuando: new Date().toISOString(),
  },
}];

